export const ELEMENT_CSS = ":host {\n  /* Public theme tokens. Hosts override any --sw-* on the element; legacy short names alias them. */\n  --sw-ink: #243a36;\n  --sw-muted: #61746d;\n  --sw-line: #dce5df;\n  --sw-accent: #176b57;\n  --sw-on-accent: #fff;\n  --sw-paper: #fff;\n  --sw-soft: #f2f6f2;\n  --sw-summary: #435b51;\n  --sw-focus: #2865bc;\n  --sw-warn-bg: #fff7e7;\n  --sw-warn-line: #a36c17;\n  --sw-warn-ink: #6b582f;\n  --sw-caution-bg: #fff4df;\n  --sw-caution-ink: #775322;\n  --sw-code-bg: #eff4f0;\n  --sw-figure-bg: #fafcf9;\n  --sw-figure-ink: #314c3b;\n  --sw-grid: #e4ece3;\n  --sw-axis: #81978a;\n  --sw-muted-line: #abbab1;\n  --sw-shape-fill: #b5d9c3;\n  --sw-vector-1: #236e5a;\n  --sw-vector-2: #b16b39;\n  --sw-positive: #438268;\n  --sw-negative: #b17b51;\n  --sw-edge: #728a7e;\n  --sw-node-line: #9fbbac;\n  --line: var(--sw-line);\n  --muted: var(--sw-muted);\n  --accent: var(--sw-accent);\n  --paper: var(--sw-paper);\n  --soft: var(--sw-soft);\n  display: block;\n  color: var(--sw-ink);\n  color-scheme: light;\n  font:\n    17px/1.85 system-ui,\n    -apple-system,\n    'Segoe UI',\n    'PingFang SC',\n    'Microsoft YaHei',\n    sans-serif;\n  overflow-wrap: anywhere;\n}\n/*\n * Light by default, because an embedded component cannot know the host page's background.\n * theme=\"auto\" follows the OS; theme=\"dark\" forces dark. Dark themes paint their own\n * background so text never ends up light-on-light inside a light host page.\n */\n@media (prefers-color-scheme: dark) {\n  :host([theme='auto']) {\n    --sw-ink: #dfe9e3;\n    --sw-muted: #9fb3a9;\n    --sw-line: #34443e;\n    --sw-accent: #5fc39f;\n    --sw-on-accent: #0f1c17;\n    --sw-paper: #16201c;\n    --sw-soft: #1e2a25;\n    --sw-summary: #b9cbc1;\n    --sw-focus: #7fb2ff;\n    --sw-warn-bg: #2d2516;\n    --sw-warn-line: #d9a648;\n    --sw-warn-ink: #e6cf9c;\n    --sw-caution-bg: #33281a;\n    --sw-caution-ink: #ecc98f;\n    --sw-code-bg: #1b2621;\n    --sw-figure-bg: #121b17;\n    --sw-figure-ink: #d3e2d9;\n    --sw-grid: #24322c;\n    --sw-axis: #6f877b;\n    --sw-muted-line: #5d7268;\n    --sw-shape-fill: #2f6b52;\n    --sw-vector-1: #6fd3ae;\n    --sw-vector-2: #f0a86e;\n    --sw-positive: #5fb48f;\n    --sw-negative: #d79a6b;\n    --sw-edge: #87a497;\n    --sw-node-line: #4f6b5e;\n    color-scheme: dark;\n    background: var(--sw-paper);\n  }\n}\n:host([theme='dark']) {\n  --sw-ink: #dfe9e3;\n  --sw-muted: #9fb3a9;\n  --sw-line: #34443e;\n  --sw-accent: #5fc39f;\n  --sw-on-accent: #0f1c17;\n  --sw-paper: #16201c;\n  --sw-soft: #1e2a25;\n  --sw-summary: #b9cbc1;\n  --sw-focus: #7fb2ff;\n  --sw-warn-bg: #2d2516;\n  --sw-warn-line: #d9a648;\n  --sw-warn-ink: #e6cf9c;\n  --sw-caution-bg: #33281a;\n  --sw-caution-ink: #ecc98f;\n  --sw-code-bg: #1b2621;\n  --sw-figure-bg: #121b17;\n  --sw-figure-ink: #d3e2d9;\n  --sw-grid: #24322c;\n  --sw-axis: #6f877b;\n  --sw-muted-line: #5d7268;\n  --sw-shape-fill: #2f6b52;\n  --sw-vector-1: #6fd3ae;\n  --sw-vector-2: #f0a86e;\n  --sw-positive: #5fb48f;\n  --sw-negative: #d79a6b;\n  --sw-edge: #87a497;\n  --sw-node-line: #4f6b5e;\n  color-scheme: dark;\n  background: var(--sw-paper);\n}\n* {\n  box-sizing: border-box;\n}\n[hidden] {\n  display: none !important;\n}\nbutton,\ninput,\ntextarea,\nselect {\n  font: inherit;\n}\nbutton,\nsummary,\ninput,\ntextarea,\na {\n  touch-action: manipulation;\n}\nbutton {\n  min-height: 44px;\n  padding: 6px 13px;\n  border: 1px solid var(--line);\n  border-radius: 9px;\n  background: var(--paper);\n  color: inherit;\n  cursor: pointer;\n  line-height: 1.5;\n}\nbutton:hover {\n  border-color: var(--accent);\n  background: var(--soft);\n}\nbutton:disabled {\n  cursor: not-allowed;\n  opacity: 0.65;\n}\n:focus-visible {\n  outline: 3px solid var(--sw-focus);\n  outline-offset: 3px;\n}\nbutton[aria-pressed='true'] {\n  background: var(--accent);\n  color: var(--sw-on-accent);\n  border-color: var(--accent);\n}\nh1,\nh2,\nh3,\np {\n  margin: 0;\n}\nh1 {\n  font-size: clamp(25px, 4.5vw, 35px);\n  line-height: 1.4;\n  letter-spacing: -0.035em;\n  font-weight: 660;\n  max-width: 26em;\n}\nh2 {\n  font-size: 20px;\n  line-height: 1.55;\n  margin-bottom: 11px;\n  letter-spacing: -0.02em;\n}\nh3 {\n  font-size: 16px;\n  line-height: 1.6;\n  margin: 8px 0;\n}\np {\n  white-space: pre-wrap;\n}\nheader .summary {\n  margin-top: 19px;\n  font-size: 18px;\n  color: var(--sw-summary);\n  max-width: 43em;\n}\n.eyebrow {\n  font-size: 11px;\n  letter-spacing: 0.12em;\n  font-weight: 700;\n  color: var(--muted);\n  margin-bottom: 10px;\n}\n.toolbar {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 7px;\n  align-items: center;\n  margin: 24px 0 8px;\n  padding-bottom: 18px;\n  border-bottom: 1px solid var(--line);\n}\n.toolbar .revision {\n  margin-left: auto;\n  color: var(--muted);\n  font-size: 12px;\n}\n.stream {\n  white-space: pre-wrap;\n  border-left: 2px solid var(--line);\n  padding-left: 16px;\n  margin: 16px 0;\n  color: var(--muted);\n}\n.notice:empty {\n  display: none;\n}\n.notice,\n.warning {\n  font-size: 14px;\n  background: var(--sw-warn-bg);\n  border-left: 3px solid var(--sw-warn-line);\n  padding: 10px 14px;\n  margin: 12px 0;\n}\n.body > section {\n  padding: 28px 0;\n  border-bottom: 1px solid var(--line);\n}\n.body > section:last-child {\n  border-bottom: 0;\n}\n.body .body-copy {\n  max-width: 44em;\n}\n.callout {\n  background: var(--soft);\n  padding: 19px 22px;\n  border-radius: 3px;\n  border-left: 3px solid var(--accent);\n}\n.qualifiers {\n  font-size: 13px;\n  color: var(--sw-warn-ink);\n  margin-top: 12px;\n}\n.qualifiers p + p {\n  margin-top: 5px;\n}\n.meta {\n  font-size: 12px;\n  color: var(--muted);\n}\n.group {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 9px;\n  margin: 12px 0;\n  align-items: center;\n}\n.figure {\n  margin-top: 18px;\n  border: 1px solid var(--line);\n  border-radius: 12px;\n  overflow: hidden;\n  background: var(--sw-figure-bg);\n}\n.figure svg {\n  display: block;\n  width: 100%;\n  height: auto;\n  max-height: 330px;\n}\n.figure figcaption {\n  font-size: 12px;\n  color: var(--muted);\n  padding: 7px 16px;\n  border-top: 1px solid var(--line);\n}\nfigure {\n  margin: 0;\n}\n.figure-tools {\n  padding: 13px 16px;\n}\n.range-label {\n  display: flex;\n  gap: 12px;\n  align-items: center;\n}\n.range-label input {\n  width: 100%;\n  min-width: 60px;\n  accent-color: var(--accent);\n}\n.metrics {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 9px 22px;\n  font-size: 14px;\n}\n.metrics strong {\n  font-variant-numeric: tabular-nums;\n  color: var(--accent);\n}\n.matrix-fields {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(50px, 110px));\n  gap: 7px;\n  margin: 12px 0;\n}\n.matrix-fields input {\n  width: 100%;\n  border: 1px solid var(--line);\n  border-radius: 7px;\n  padding: 6px;\n  background: var(--paper);\n  color: inherit;\n}\ndetails {\n  margin-top: 14px;\n}\nsummary {\n  cursor: pointer;\n  min-height: 44px;\n  font-size: 14px;\n  color: var(--accent);\n  padding: 5px 0;\n}\nselect,\ninput[type='number'],\ninput[type='range'] {\n  min-height: 44px;\n}\ndetails[open] > summary {\n  margin-bottom: 10px;\n}\n/* Placement 'replace': verbatim source of a component, collapsed under it. */\ndetails.sw-original {\n  margin-top: 8px;\n}\ndetails.sw-original > summary {\n  font-size: 13px;\n}\n.sw-original-text {\n  white-space: pre-wrap;\n  margin: 0;\n  padding: 8px 12px;\n  border-left: 3px solid var(--sw-line);\n  color: var(--sw-muted);\n}\ntable {\n  border-collapse: collapse;\n  width: 100%;\n  font-size: 14px;\n  line-height: 1.7;\n  text-align: left;\n}\nth,\ntd {\n  padding: 11px 13px;\n  border-bottom: 1px solid var(--line);\n  vertical-align: top;\n  min-width: 100px;\n}\nth {\n  font-weight: 650;\n  background: var(--soft);\n}\nth:first-child,\ntd:first-child {\n  padding-left: 10px;\n}\n.table-wrap {\n  overflow: auto;\n  margin-top: 15px;\n  max-width: 100%;\n  border: 1px solid var(--line);\n  border-radius: 8px;\n}\nol {\n  padding-left: 24px;\n  margin: 12px 0;\n}\nli {\n  padding: 5px 0 5px 8px;\n}\npre {\n  max-width: 100%;\n  overflow: auto;\n  background: var(--sw-code-bg);\n  padding: 18px;\n  border-radius: 9px;\n  font:\n    13px/1.8 ui-monospace,\n    Consolas,\n    monospace;\n  tab-size: 2;\n}\ncode {\n  white-space: pre;\n}\nmath {\n  font-size: 1.3em;\n  margin: 18px 0;\n  max-width: 100%;\n  overflow: auto;\n}\n.claim {\n  padding: 17px 0;\n  border-top: 1px solid var(--line);\n}\n.claim:first-child {\n  border-top: 0;\n}\n.badge {\n  display: inline-block;\n  font-size: 11px;\n  padding: 2px 8px;\n  line-height: 1.7;\n  border: 1px solid var(--line);\n  border-radius: 5px;\n  margin-right: 9px;\n  vertical-align: 2px;\n  background: var(--soft);\n}\n.badge.caution {\n  background: var(--sw-caution-bg);\n  color: var(--sw-caution-ink);\n}\n.citation {\n  font-size: 12px;\n  margin: 5px 5px 0 0;\n  color: var(--accent);\n}\n.source {\n  font-size: 14px;\n  border: 1px solid var(--line);\n  padding: 16px;\n  margin-top: 10px;\n  border-radius: 7px;\n}\n.source a {\n  color: var(--accent);\n}\n.source p {\n  margin: 8px 0;\n}\n.source:focus {\n  outline: 3px solid var(--sw-focus);\n}\n.question {\n  font-size: 18px;\n  margin: 16px 0;\n  font-weight: 550;\n}\n.answer-input {\n  display: block;\n  width: 100%;\n  resize: vertical;\n  min-height: 105px;\n  max-height: 400px;\n  border: 1px solid var(--line);\n  border-radius: 10px;\n  padding: 12px;\n  color: inherit;\n  background: var(--paper);\n  font-size: 15px;\n}\n.feedback {\n  font-size: 13px;\n  color: var(--accent);\n  margin-top: 8px;\n}\n.answer {\n  padding: 14px;\n  background: var(--soft);\n  border-radius: 7px;\n  margin-top: 12px;\n}\n.hint {\n  font-size: 14px;\n  padding: 6px 0;\n}\n.plain {\n  white-space: pre-wrap;\n  font: inherit;\n  background: transparent;\n  padding: 22px 0;\n  overflow-wrap: anywhere;\n}\n.notes {\n  margin-top: 24px;\n}\n.sr {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  overflow: hidden;\n  clip-path: inset(50%);\n  white-space: nowrap;\n}\n.mono {\n  font-family: ui-monospace, Consolas, monospace;\n}\n@media (max-width: 480px) {\n  :host {\n    font-size: 16px;\n    line-height: 1.8;\n  }\n  .toolbar {\n    gap: 5px;\n  }\n  .toolbar button {\n    padding: 6px 10px;\n    font-size: 13px;\n  }\n  .toolbar .revision {\n    width: 100%;\n    margin: 3px 0 0;\n  }\n  .body > section {\n    padding: 23px 0;\n  }\n  .figure-tools {\n    padding: 12px;\n  }\n  .range-label {\n    flex-wrap: wrap;\n  }\n  h2 {\n    font-size: 19px;\n  }\n  header .summary {\n    font-size: 17px;\n  }\n  th,\n  td {\n    min-width: 94px;\n  }\n  .callout {\n    padding: 14px;\n  }\n  .metrics {\n    gap: 5px 15px;\n  }\n}\n@media (prefers-reduced-motion: reduce) {\n  * {\n    scroll-behavior: auto !important;\n    animation: none !important;\n    transition: none !important;\n  }\n}\n:host([data-reduced-motion]) *,\n:host([data-reduced-motion]) *::before,\n:host([data-reduced-motion]) *::after {\n  scroll-behavior: auto !important;\n  animation: none !important;\n  transition: none !important;\n}\n@media print {\n  .toolbar,\n  .group,\n  .matrix-fields,\n  .range-label,\n  button,\n  .answer-input,\n  .notes,\n  .stream {\n    display: none !important;\n  }\n  :host {\n    font-size: 12pt;\n    color: black;\n  }\n  .body > section {\n    break-inside: avoid;\n  }\n  .figure {\n    break-inside: avoid;\n  }\n  details:not([open]) {\n    display: none;\n  }\n}\n\n.range-label {\n  display: grid;\n  grid-template-columns: 80px minmax(0, 1fr);\n  align-items: center;\n  white-space: nowrap;\n}\n.range-label input {\n  min-width: 0;\n  width: 100%;\n}\nheader .warning {\n  margin-top: 18px;\n  font-size: 14px;\n}\n\n.diagram-viewport {\n  overflow-x: auto;\n}\n.diagram-viewport svg {\n  min-width: 520px;\n}\n\n/* Safe Markdown subset inside prose/callout bodies. */\n.markdown > :first-child {\n  margin-top: 0;\n}\n.markdown p {\n  white-space: normal;\n  margin: 0 0 0.9em;\n}\n.markdown h3,\n.markdown h4,\n.markdown h5,\n.markdown h6 {\n  margin: 1.2em 0 0.4em;\n}\n.markdown ul,\n.markdown ol {\n  padding-left: 24px;\n  margin: 0.4em 0 0.9em;\n}\n.markdown h3 {\n  font-size: 18px;\n}\n.markdown h4 {\n  font-size: 16.5px;\n}\n.markdown h5,\n.markdown h6 {\n  font-size: 15.5px;\n}\n.markdown blockquote {\n  margin: 0 0 0.9em;\n  padding-left: 14px;\n  border-left: 3px solid var(--sw-line);\n  color: var(--sw-muted);\n}\n.markdown hr {\n  border: 0;\n  border-top: 1px solid var(--sw-line);\n  margin: 1.4em 0;\n}\n.markdown :not(pre) > code {\n  font:\n    0.88em ui-monospace,\n    Consolas,\n    monospace;\n  background: var(--sw-code-bg);\n  padding: 1px 5px;\n  border-radius: 4px;\n  white-space: break-spaces;\n}\n.markdown a {\n  color: var(--sw-accent);\n}\n.markdown .table-wrap {\n  margin: 0.4em 0 1em;\n}\n\n/* 0.3: bound numbers, calc, timeline, checklist, progressive composition. */\n.bound {\n  font-variant-numeric: tabular-nums;\n  font-weight: 650;\n  color: var(--accent);\n  border-bottom: 1px dotted currentColor;\n  padding: 0 1px;\n  transition: background-color 0.25s;\n}\n.bound.waiting {\n  color: var(--muted);\n  border-bottom-style: dashed;\n}\n.checks {\n  margin-top: 12px;\n}\n.checks strong {\n  display: block;\n  font-size: 13px;\n  margin-bottom: 4px;\n}\n.calc {\n  margin-top: 18px;\n  border: 1px solid var(--line);\n  border-radius: 12px;\n  background: var(--sw-figure-bg);\n  padding: 18px 18px 8px;\n}\n.calc-inputs {\n  display: grid;\n  gap: 14px;\n}\n.calc-row {\n  display: grid;\n  grid-template-columns: minmax(96px, 150px) minmax(0, 1fr) 112px 28px;\n  gap: 12px;\n  align-items: center;\n}\n.calc-row label {\n  display: flex;\n  flex-direction: column;\n  line-height: 1.35;\n  font-size: 15px;\n}\n.calc-row small {\n  font-size: 11px;\n  color: var(--muted);\n}\n.calc-row input[type='range'] {\n  width: 100%;\n  min-width: 0;\n  accent-color: var(--accent);\n}\n.calc-number {\n  width: 100%;\n  border: 1px solid var(--line);\n  border-radius: 7px;\n  padding: 5px 8px;\n  background: var(--paper);\n  color: inherit;\n  font-variant-numeric: tabular-nums;\n  text-align: right;\n}\n.calc-row .unit {\n  font-size: 13px;\n  color: var(--muted);\n}\n.calc-outputs {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 10px;\n  margin: 18px 0 0;\n  padding-top: 16px;\n  border-top: 1px solid var(--line);\n}\n.calc-outputs .out {\n  flex: 1 1 130px;\n  padding: 10px 14px;\n  border-radius: 9px;\n  background: var(--paper);\n  border: 1px solid var(--line);\n}\n.calc-outputs dt {\n  font-size: 12px;\n  color: var(--muted);\n}\n.calc-outputs dd {\n  margin: 0;\n  font-size: 18px;\n  font-weight: 650;\n  font-variant-numeric: tabular-nums;\n}\n.calc-outputs .out.main {\n  flex-basis: 100%;\n  background: var(--soft);\n  border-color: var(--accent);\n}\n.calc-outputs .out.main dd {\n  font-size: 30px;\n  color: var(--accent);\n  letter-spacing: -0.02em;\n}\n.formulas {\n  margin-top: 4px;\n}\n.timeline {\n  list-style: none;\n  padding: 0;\n  margin: 18px 0 0;\n  position: relative;\n}\n.timeline li {\n  position: relative;\n  padding: 0 0 20px 30px;\n}\n.timeline li::before {\n  content: '';\n  position: absolute;\n  left: 6px;\n  top: 10px;\n  bottom: -10px;\n  width: 2px;\n  background: var(--line);\n}\n.timeline li:last-child::before {\n  display: none;\n}\n.timeline li::after {\n  content: '';\n  position: absolute;\n  left: 0;\n  top: 6px;\n  width: 14px;\n  height: 14px;\n  border-radius: 50%;\n  background: var(--paper);\n  border: 3px solid var(--accent);\n}\n.timeline .when {\n  display: block;\n  font-size: 12px;\n  letter-spacing: 0.04em;\n  color: var(--accent);\n  font-weight: 650;\n}\n.timeline strong {\n  font-weight: 620;\n}\n.timeline .detail {\n  font-size: 14px;\n  color: var(--muted);\n}\n.checklist {\n  list-style: none;\n  padding: 0;\n  margin: 14px 0 6px;\n  border: 1px solid var(--line);\n  border-radius: 10px;\n  overflow: hidden;\n}\n.checklist li {\n  display: flex;\n  gap: 12px;\n  align-items: flex-start;\n  padding: 11px 14px;\n  border-top: 1px solid var(--line);\n}\n.checklist li:first-child {\n  border-top: 0;\n}\n.checklist input {\n  width: 20px;\n  height: 20px;\n  margin-top: 5px;\n  flex: none;\n  accent-color: var(--accent);\n}\n.checklist input:checked + label {\n  color: var(--muted);\n  text-decoration: line-through;\n}\n.skeleton {\n  padding: 24px 0;\n}\n.skeleton .bar {\n  height: 120px;\n  margin-top: 10px;\n  border-radius: 12px;\n  background: linear-gradient(90deg, var(--soft), var(--sw-figure-bg), var(--soft));\n  background-size: 200% 100%;\n  animation: sw-shimmer 1.4s linear infinite;\n}\n.skeleton .bar.short {\n  height: 18px;\n  width: 55%;\n}\n@keyframes sw-shimmer {\n  to {\n    background-position: -200% 0;\n  }\n}\n[data-composing] .body > section:not(.skeleton):not([data-type='prose']) {\n  animation: sw-in 0.35s ease-out;\n}\n@keyframes sw-in {\n  from {\n    opacity: 0;\n    transform: translateY(6px);\n  }\n}\n@media (max-width: 560px) {\n  .calc {\n    padding: 14px 12px 6px;\n  }\n  .calc-row {\n    grid-template-columns: minmax(0, 1fr) 96px 24px;\n    gap: 6px 10px;\n  }\n  .calc-row label {\n    grid-column: 1 / -1;\n    flex-direction: row;\n    justify-content: space-between;\n    align-items: baseline;\n  }\n  .calc-outputs .out.main dd {\n    font-size: 25px;\n  }\n}\n@media print {\n  .calc-row input[type='range'],\n  .skeleton {\n    display: none !important;\n  }\n}\n\n/* 0.5 data views use host theme tokens, inert content and no motion. */\n.data-controls { display:flex; flex-wrap:wrap; gap:.6rem; align-items:center; }\n.data-controls input { flex:1; min-width:140px; border:1px solid var(--sw-line); border-radius:8px; padding:.6rem; background:var(--sw-paper); color:var(--sw-ink); }\n.json-children { margin-inline-start:1rem; padding-inline-start:.8rem; border-inline-start:1px solid var(--sw-line); }\n.json-scalar { font-family:monospace; padding:.2rem 0; white-space:pre-wrap; overflow-wrap:anywhere; }\n.json-node { margin:.4rem 0; }\n.diff-view span { white-space:pre-wrap; overflow-wrap:anywhere; }\n.diff-view [data-diff=added] { color:var(--sw-positive); }\n.diff-view [data-diff=removed] { color:var(--sw-negative); }\n.diff-view [data-diff=hunk] { font-weight:700; }\n.data-plot { width:100%; max-width:700px; height:auto; }\n.plot-axis { stroke:var(--sw-axis); stroke-width:1; }\n.plot-line { stroke:var(--sw-accent); stroke-width:2; }\n.plot-point { fill:var(--sw-accent); }\n.plot-label { fill:var(--sw-ink); font-size:12px; }\n/* Readability aids: sticky header, aligned numbers, local summary row, typed JSON values, diff gutter. */\n.data-table { max-height:min(70vh, 640px); }\n.data-table thead th { position:sticky; top:0; z-index:1; }\n.data-table th.num, .data-table td.num { text-align:right; font-variant-numeric:tabular-nums; }\n.data-table tfoot td { position:sticky; bottom:0; background:var(--sw-soft); color:var(--sw-muted); font-size:13px; white-space:pre-line; border-top:1px solid var(--sw-line); }\n.json-string { color:var(--sw-vector-1); }\n.json-number { color:var(--sw-vector-2); font-variant-numeric:tabular-nums; }\n.json-boolean { color:var(--sw-accent); }\n.json-null { color:var(--sw-muted); font-style:italic; }\n.diff-view .diff-ln { color:var(--sw-muted); user-select:none; -webkit-user-select:none; }\n.diff-view [data-diff=file] { font-weight:700; color:var(--sw-muted); }\n.diff-stat { font-variant-numeric:tabular-nums; font-weight:600; }\n.plot-grid { stroke:var(--sw-grid); stroke-width:1; }\n.plot-tick { fill:var(--sw-muted); font-size:11px; }\n.plot-summary { margin-top:.4rem; }\n.manual-copy textarea { display:block; width:100%; max-width:100%; min-height:8rem; padding:.75rem; border:1px solid var(--sw-line); border-radius:8px; background:var(--sw-paper); color:var(--sw-ink); font:13px/1.6 ui-monospace,monospace; resize:vertical; }\n.print-data { display:none; }\n@media print {\n  .screen-data { display:none!important; }\n  .print-data { display:block!important; }\n  .print-data .table-wrap { overflow:visible; max-height:none; max-width:none; border:0; border-radius:0; }\n  .print-data table { width:100%; table-layout:auto; font-size:9pt; }\n  .print-data th,.print-data td { min-width:0; padding:5px 7px; overflow-wrap:anywhere; }\n  .print-data thead { display:table-header-group; }\n  .print-data tfoot { display:table-row-group; }\n  .print-data tr { break-inside:avoid; }\n  .body > section[data-type='table'],.body > section[data-type='json'] { break-inside:auto; }\n  .print-json { white-space:pre-wrap; overflow:visible; overflow-wrap:anywhere; background:transparent; padding:0; font-size:10pt; }\n}\n\n/* chrome=\"none\": single blocks inside a host's own message layout. Hosts theme through --sw-* tokens. */\n:host([chrome='none']) {\n  font: var(--sw-font, inherit);\n  line-height: inherit;\n}\n:host([chrome='none']) [part='header'],\n:host([chrome='none']) [part='toolbar'],\n:host([chrome='none']) [part='sources'] {\n  display: none !important;\n}\n:host([chrome='none']) .body > section {\n  padding: 0;\n  border-bottom: 0;\n}\n:host([chrome='none']) .body > section > h2:first-child {\n  font-size: 15px;\n  margin-bottom: 6px;\n}\n/*\n * Controlled motion presets (data-motion set once per block by the runtime hints).\n * Every rule animates FROM a hidden/plain state TO the normal resting style, so with\n * reduced motion (rules above) or no animation support the block is simply complete.\n */\nsection[data-motion='reveal'] {\n  animation: sw-in 0.42s ease-out backwards;\n}\nsection[data-motion='stagger'] li,\nsection[data-motion='stagger'] tbody tr {\n  animation: sw-in 0.36s ease-out backwards;\n  animation-delay: calc(var(--sw-i, 0) * 70ms);\n}\nsection[data-motion='step-through'] > ol > li {\n  animation: sw-step 0.9s ease-in-out backwards;\n  animation-delay: calc(var(--sw-i, 0) * 420ms);\n  border-radius: 6px;\n}\n@keyframes sw-step {\n  0% {\n    opacity: 0.25;\n    background: transparent;\n  }\n  35% {\n    opacity: 1;\n    background: color-mix(in srgb, var(--sw-accent) 16%, transparent);\n  }\n  100% {\n    background: transparent;\n  }\n}\nsection[data-motion='draw'] svg polyline,\nsection[data-motion='draw'] svg path.sw-rough,\nsection[data-motion='draw'] svg .plot-line {\n  stroke-dasharray: 1;\n  animation: sw-draw 0.9s ease-out backwards;\n}\nsection[data-motion='draw'] svg rect[data-value] {\n  transform-box: fill-box;\n  transform-origin: left center;\n  animation: sw-grow 0.6s ease-out backwards;\n  animation-delay: calc(var(--sw-i, 0) * 60ms);\n}\nsection[data-motion='draw'] svg circle {\n  animation: sw-fade 0.3s ease-out backwards;\n  animation-delay: 0.6s;\n}\n@keyframes sw-draw {\n  from {\n    stroke-dashoffset: 1;\n  }\n  to {\n    stroke-dashoffset: 0;\n  }\n}\n@keyframes sw-grow {\n  from {\n    transform: scaleX(0);\n  }\n}\n@keyframes sw-fade {\n  from {\n    opacity: 0;\n  }\n}\nsection[data-motion='highlight'] .sw-key,\nsection[data-motion='highlight'] table th {\n  animation: sw-pulse 1.2s ease-in-out 2 backwards;\n}\nsection[data-motion='highlight'] svg rect.sw-key {\n  stroke: var(--sw-accent);\n  stroke-width: 2;\n}\n@keyframes sw-pulse {\n  50% {\n    filter: brightness(1.12);\n    outline: 2px solid color-mix(in srgb, var(--sw-accent) 45%, transparent);\n  }\n}\nsection[data-motion='write'] .sw-derivation > li {\n  animation: sw-write 0.7s steps(18, end) backwards;\n  animation-delay: calc(var(--sw-i, 0) * 650ms);\n}\n@keyframes sw-write {\n  from {\n    clip-path: inset(0 100% 0 0);\n  }\n  to {\n    clip-path: inset(0 0 0 0);\n  }\n}\n/* Board derivation (板书推导). Hand font only from the system or the host (--sw-hand-font). */\n.sw-derivation {\n  list-style: none;\n  margin: 8px 0;\n  padding: 12px 16px;\n  border-radius: 10px;\n  background: var(--sw-figure-bg);\n  counter-reset: sw-line;\n}\n.sw-derivation > li {\n  position: relative;\n  padding: 3px 0 3px 2.2em;\n  counter-increment: sw-line;\n  font-variant-numeric: tabular-nums;\n}\n.sw-derivation > li::before {\n  content: counter(sw-line);\n  position: absolute;\n  left: 0;\n  color: var(--sw-muted);\n  font-size: 0.8em;\n  line-height: 2.2;\n}\n.sw-math-inline {\n  font-family: 'Cambria Math', 'STIX Two Math', 'Latin Modern Math', 'Times New Roman', serif;\n  font-style: italic;\n}\n.sw-derivation-note {\n  margin-left: 0.8em;\n}\n/* Sketch (hand-drawn) style: deterministic rough strokes from motion.mjs, system fonts only. */\nsection[data-sketch] {\n  position: relative;\n  border-color: transparent;\n  font-family: var(\n    --sw-hand-font,\n    'Kaiti SC',\n    'STKaiti',\n    'KaiTi',\n    'Xingkai SC',\n    'Segoe Print',\n    'Bradley Hand',\n    'Comic Sans MS',\n    cursive,\n    inherit\n  );\n}\nsection[data-sketch] .sw-sketch-frame {\n  position: absolute;\n  inset: 0;\n  width: 100%;\n  height: 100%;\n  pointer-events: none;\n  overflow: visible;\n}\nsection[data-sketch] .sw-sketch-frame path {\n  stroke: var(--sw-muted-line);\n  stroke-width: 1.4;\n  stroke-linecap: round;\n}\nsection[data-sketch] svg text {\n  font-family: inherit;\n}\nsection[data-sketch] svg .sw-rough,\nsection[data-sketch] svg .sw-rough-line {\n  stroke-linecap: round;\n  stroke-linejoin: round;\n}\nsection[data-sketch] svg path[data-rough='rect'] {\n  stroke: var(--sw-figure-ink);\n  stroke-width: 1.3;\n}\nsection[data-sketch] .sw-derivation {\n  background: color-mix(in srgb, var(--sw-figure-bg) 70%, var(--sw-soft));\n}\n/* The frame uses non-scaling strokes (dash lengths would follow screen space), so it fades in instead of drawing. */\nsection[data-sketch][data-motion] .sw-sketch-frame {\n  animation: sw-fade 0.6s ease-out backwards;\n}\n/* Annotations: verbatim phrases, underlined or circled like a teacher's pen. */\nmark.sw-annot {\n  color: inherit;\n  background: linear-gradient(var(--sw-warn-line), var(--sw-warn-line)) no-repeat 0 100% / 100% 2px;\n  padding-bottom: 1px;\n}\nmark.sw-annot[data-kind='circle'] {\n  background: none;\n  border: 1.5px solid var(--sw-warn-line);\n  border-radius: 45% 55% 50% 48% / 60% 45% 55% 40%;\n  padding: 0 3px;\n}\nmark.sw-annot[data-kind='underline'] {\n  animation: sw-underline 0.6s ease-out backwards;\n  animation-delay: calc(0.3s + var(--sw-i, 0) * 250ms);\n}\n@keyframes sw-underline {\n  from {\n    background-size: 0% 2px;\n  }\n}\n";
